#!/usr/bin/env python3
import hashlib,json,re,struct
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'docs/research'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=D/'dedup-model-bank-recovery-remaining-native-20261011.json';r=json.loads(p.read_text());assert r['status']=='complete_bounded_actual_cpu_remaining_recovery_controls' and r['completed']==2 and len(r['results'])==2;pins=dict(r['pins']);assert all(sha(k)==v for k,v in pins.items())
 mp=D/'dedup-model-bank-joint-recovery-native-snapshot-20261011.json';m=json.loads(mp.read_text());assert all(sha(Path(m['snapshot'])/k)==v for k,v in m['file_hashes'].items());gp=D/'dedup-model-bank-joint-recovery-verification-20261011.json';g=json.loads(gp.read_text());assert g['status']=='verified_134_tests_model_bank_joint_recovery' and all(sha(k)==v for k,v in g['pins'].items())
 prefix=D/'dedup-model-bank-all-positives-prefix-0007-audit-20261011.json';pr=json.loads(prefix.read_text());assert all(sha(k)==v for k,v in pr['pins'].items());assert {v['baseline_index']:v['status'] for v in pr['rows'] if v['baseline_index'] in [57,153]}=={57:'inconclusive',153:'inconclusive'}
 refs=[D/'dedup-joint-recovery-native-20261011.json',D/'dedup-joint-recovery-sampling-native-20261011.json'];old=[json.loads(x.read_text()) for x in refs];previous=[json.loads(x['results'][0]['stdout'])['pairs'][0]['evidence'] for x in old];bits=lambda h:[[struct.unpack('>Q',struct.pack('>d',x))[0] for x in row] for row in h];results=[]
 for index,(row,v,ref) in enumerate(zip(r['plan'],r['results'],previous)):
  assert row['baseline_index']==[57,153][index] and row['opposite_trials']==[4096,1000000][index];assert v['baseline_index']==row['baseline_index'] and v['status']=='supported' and v['returncode']==0;assert sha(v['log'])==v['log_sha256'] and Path(v['log']).read_text()==v['stdout']+v['stderr'];pins[v['log']]=v['log_sha256'];value=json.loads(v['stdout']);d=value['detail'];assert value['supported'] is True and value['managed_used']==0 and value['opposite_trials']==row['opposite_trials'];assert d['terminal']=='joint_opposite_native' and d['primary_insufficient']!='None';assert bits(d['transform'])==bits(ref['transform']) and d['pixels']==ref['pixels'];assert d['candidate_points']==ref['candidate_points'] and d['native_recipes']==ref['native_recipes'] and d['reflected_proposal_source']==ref['reflected_proposal_source'];px=d['pixels'];assert px['supported'] and min(px['anchors'])>=10 and all(x['informative_pairs']>=1000 and x['valid_sites']/x['sites']>=.3 and x['agreeing_pairs']/x['informative_pairs']>=.9 for x in px['directions']);rss=re.search(r'(\d+)\s+maximum resident set size',v['stderr']);assert rss;results.append({'baseline_index':row['baseline_index'],'opposite_trials':row['opposite_trials'],'prior_joint_native_transform_and_pixels_identical':True,'pixels':px,'candidate_points':d['candidate_points'],'managed_used':0,'managed_peak':value['managed_peak'],'max_rss_bytes':int(rss[1]),'elapsed_seconds':v['elapsed_seconds']})
 pins.update({str(x):sha(x) for x in [p,mp,gp,prefix,*refs,Path(__file__)]});out=D/'dedup-model-bank-recovery-remaining-native-audit-20261011.json';assert not out.exists();out.write_text(json.dumps({'status':'verified_actual_cpu_bank_then_opposite_204100_207700','pins':pins,'results':results,'scope':'Two actual CPU integrated pair recovery controls on134-test frozen core, previously bank-only unknown, same original pixel and transform evidence as qualified opposite-native controls. Not full combined458/collection CPU/semantic negatives/formats/platforms/all500/RSS cap/speedup qualification.'},indent=2)+'\n');print('Verified actual CPU integrated204100 and207700 recovery')
if __name__=='__main__':main()
